<?php require __DIR__ . '/php/footer.php'; require __DIR__ . '/php/connect.php'; $token=$_GET['token']??$_POST['token']??''; $done=false; if($_SERVER['REQUEST_METHOD']==='POST'&&strlen($_POST['password']??'')>=8){$hash=password_hash($_POST['password'],PASSWORD_DEFAULT); $stmt=$mysqli->prepare('UPDATE users SET password_hash=?, reset_token=NULL, reset_expires=NULL WHERE reset_token=? AND reset_expires>NOW()'); $stmt->bind_param('ss',$hash,$token); $stmt->execute(); $done=$stmt->affected_rows>0;} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset Password</title><link rel="stylesheet" href="css/styles.css"></head><body><header><h1>Reset Password</h1><nav><a href="login.php">Login</a></nav></header><main><section class="card"><?php if($done):?><div class="notice success">Password reset completed.</div><?php else:?><form method="post"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><label>New password</label><input name="password" type="password" minlength="8" required><button>Reset</button></form><?php endif;?></section></main><?php exam_footer(); ?></body></html>
